def balanced_brackets(text):
    closer_to_opener = {")": "(", "]": "[", "}": "{"}
    stack = []
    for char in text:
        if char in "([{":
            stack.append(char)
        elif char in ")]}":
            if not stack or stack[-1] != closer_to_opener[char]:
                return False
            stack.pop()
        else:
            raise ValueError("expected bracket-only input")
    return not stack

print(balanced_brackets("([])"))
print(balanced_brackets("([)]"))
print(balanced_brackets("(("))
print(balanced_brackets(""))

def next_strictly_greater(values):
    answer = [-1] * len(values)
    waiting = []
    for index, value in enumerate(values):
        while waiting and values[waiting[-1]] < value:
            answer[waiting.pop()] = index
        waiting.append(index)
    return answer

print(next_strictly_greater([2, 2, 3, 1]))
print(next_strictly_greater([3, 2, 1]))

def next_greater(a):
    indexes = next_strictly_greater(a)
    return [" ".join(str(0 if index == -1 else index + 1) for index in indexes)]

from collections import deque

def window_maximum(values, width):
    if type(width) is not int or not 1 <= width <= len(values):
        raise ValueError("width outside1..n")
    candidates = deque()
    result = []
    for index, value in enumerate(values):
        while candidates and candidates[0] <= index - width:
            candidates.popleft()
        while candidates and values[candidates[-1]] <= value:
            candidates.pop()
        candidates.append(index)
        if index >= width - 1:
            result.append(values[candidates[0]])
    return result

print(window_maximum([1, 3, 3, 2, 5], 3))

