def check(expr):
    """Ignore nonbrackets but count their character positions."""
    pairs = {')': '(', ']': '[', '}': '{'}
    pending = []
    for (pos, char) in enumerate(expr, 1):
        if char in '([{':
            pending.append((char, pos))
        elif char in pairs:
            if not pending or pending[-1][0] != pairs[char]:
                return f'ERR {pos}'
            pending.pop()
    return f'ERR {pending[0][1]}' if pending else 'OK'

print(check('a(b[c]d)'))
print(check('([)]'))
print(check(' ([x'))
print(check(''))

