def run_stack(ops):
    """PUSH argument is a string in the supplied parser."""
    entries = []
    out = []
    for op in ops:
        key = op[0]
        if key == 'PUSH':
            value = int(op[1])
            minimum = value if not entries else min(value, entries[-1][1])
            entries.append((value, minimum))
        elif key not in ('POP', 'TOP', 'MIN'):
            raise ValueError('unknown operation')
        elif not entries:
            out.append('EMPTY')
        elif key == 'POP':
            out.append(str(entries.pop()[0]))
        elif key == 'TOP':
            out.append(str(entries[-1][0]))
        else:
            out.append(str(entries[-1][1]))
    return out

print(run_stack([['PUSH', '5'], ['PUSH', '3'], ['PUSH', '3'], ['POP'], ['MIN'], ['POP'], ['MIN']]))
print(run_stack([['POP'], ['TOP'], ['MIN']]))

