def window_max(k, a):
    candidates = deque()
    maxima = []
    for (i, value) in enumerate(a):
        while candidates and candidates[0] <= i - k:
            candidates.popleft()
        while candidates and a[candidates[-1]] <= value:
            candidates.pop()
        candidates.append(i)
        if i >= k - 1:
            maxima.append(str(a[candidates[0]]))
    return [' '.join(maxima)]

